import{_ as n,C as o,o as i,c as r,j as t,a as s,E as d,ag as l}from"./chunks/framework.DMVuHR7L.js";const y=JSON.parse('{"title":"Scripting","description":"","frontmatter":{},"headers":[],"relativePath":"features/scripting.md","filePath":"features/scripting.md","lastUpdated":1779922360000}'),h={name:"features/scripting.md"};function c(p,e,u,g,k,m){const a=o("ThemeImage");return i(),r("div",null,[e[0]||(e[0]=t("h1",{id:"scripting",tabindex:"-1"},[s("Scripting "),t("a",{class:"header-anchor",href:"#scripting","aria-label":'Permalink to "Scripting"'},"​")],-1)),e[1]||(e[1]=t("p",null,[s("The Scripting widget turns one shell script into a custom control panel. You write shell "),t("strong",null,"functions"),s("; you add "),t("strong",null,"controls"),s(` that run them or feed them values. It's a Tasker-style toolbox for the workflows you repeat — "Package toolbox", "Performance lab", an app-debugger panel — without building a real app.`)],-1)),d(a,{"src-dark":"/img/features/scripting-default.png","src-light":"/img/features/scripting-default-light.png",alt:"Scripting tile — a Package toolbox panel with a text input, action buttons, and a console"}),e[2]||(e[2]=l(`<h2 id="the-mental-model" tabindex="-1">The mental model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The mental model&quot;">​</a></h2><p>One panel owns one script. Every control&#39;s <strong>label</strong> decides the name the script sees — there&#39;s no second naming step:</p><ul><li>An <strong>input</strong> labelled <code>Package</code> exports its value as the env var <code>$PACKAGE</code>.</li><li>An <strong>action button</strong> labelled <code>Force stop</code> calls the function <code>force_stop</code> when pressed.</li><li>A bound <strong>display</strong> labelled <code>Battery temperature</code> calls <code>battery_temp</code> and shows its output.</li></ul><p>Names are derived deterministically — uppercased and snake-cased for variables, lowercased for functions (so <code>Force stop</code> → <code>$FORCE_STOP</code> as a value, <code>force_stop()</code> as a function). They use underscores, never hyphens, because the device shell (mksh) requires it.</p><p>Every input&#39;s current value is exported on <strong>every</strong> run, so any function can read any input. A <code>$PACKAGE</code> text field can drive a whole row of buttons:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">force_stop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> force-stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PACKAGE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clear_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PACKAGE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()       { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dumpsys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PACKAGE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> versionName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span></code></pre></div><h2 id="how-runs-work" tabindex="-1">How runs work <a class="header-anchor" href="#how-runs-work" aria-label="Permalink to &quot;How runs work&quot;">​</a></h2><p>Each run re-sources the whole script and calls one function, with input values supplied as environment variables. Values are passed as separate arguments, never spliced into the command text — so a value like <code>; rm -rf /</code> is inert data, not code. Output (stdout, stderr, exit code) lands in the panel&#39;s <strong>console</strong>.</p><p>Action-button runs are one-shot — the script is re-sourced each time rather than kept in a long-lived shell, so a function is always defined by the current script and always sees the current input values. For something that keeps running — following <code>logcat | grep &quot;$PACKAGE&quot;</code>, for instance — use a <strong><a href="#daemon">Daemon</a></strong>, which manages a long-lived background process and streams its output to the console.</p><p>The console renders ANSI colours, so <code>echo -e &quot;\\e[31m…\\e[0m&quot;</code> (and emoji) show up the way they would in a terminal.</p><h2 id="controls" tabindex="-1">Controls <a class="header-anchor" href="#controls" aria-label="Permalink to &quot;Controls&quot;">​</a></h2><p><strong>Inputs</strong> carry a value: text field, slider, knob, toggle, select, stepper. A toggle exports <code>1</code> / <code>0</code> by default — set its optional <strong>Values</strong> to export a custom off / on pair instead; everything else exports its value verbatim. An input&#39;s <strong>On change</strong> setting decides what a change does: refresh the displays that read it, do nothing, or <strong>run a function</strong> — the function derived from its label, fired the moment the value changes. That last option lets a toggle send a broadcast on flip without a separate button.</p><p><strong>Action button</strong> runs a function once. Mark it <em>Confirm before running</em> for destructive operations and it opens a Cancel / Run popover first.</p><p><strong>Daemon</strong> runs a function as a managed background process — declarative, not a click. It&#39;s a desired-state toggle: while active, the runtime keeps the process running and streams its output to the bound console; toggle it off and the process is stopped. See <a href="#daemon">Daemon</a> below.</p><p><strong>Displays</strong> show a bound function&#39;s output:</p><table tabindex="0"><thead><tr><th>Display</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Console</strong></td><td>The most recent run — stdout, stderr, and the exit code (or a live, scrolling feed when fed by a daemon). ANSI colours and emoji are rendered. On by default.</td></tr><tr><td><strong>Readout</strong></td><td>A big number + unit pulled from the output.</td></tr><tr><td><strong>Status pill</strong></td><td>A label + the output&#39;s last line, coloured by exit status.</td></tr><tr><td><strong>Gauge</strong></td><td>The output as a value on a min/max arc.</td></tr><tr><td><strong>LED</strong></td><td>A coloured indicator driven by the output (<code>green</code> / <code>amber</code> / <code>red</code> / <code>blue</code> / <code>off</code>, or truthiness).</td></tr></tbody></table><p>Displays refresh on a configurable <strong>auto-poll</strong> interval (off by default) and, optionally, whenever an input they read changes.</p><p><strong>Sections</strong> group controls under a heading. They&#39;re visual only — they don&#39;t change the shared environment.</p><h2 id="control-reference" tabindex="-1">Control reference <a class="header-anchor" href="#control-reference" aria-label="Permalink to &quot;Control reference&quot;">​</a></h2><p>Each control&#39;s <strong>label</strong> is the only name you set — it derives the env var (inputs) or, for action buttons, the function called. Every control&#39;s (and section&#39;s) <strong>description</strong> accepts basic markdown — <code>**bold**</code>, <code>*italic*</code>, <code>\`code\`</code>, and <code>[links](https://…)</code> — shown inline or in its tooltip. Pair each control with a function in the script. The examples below assume one script with these functions:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">force_stop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()    { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">am</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> force-stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PACKAGE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set_brightness</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(){ </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">settings</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> put</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> screen_brightness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BRIGHTNESS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">battery_temp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()  { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dumpsys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> battery</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/temperature/ { print $2 / 10 }&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">charging</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()      { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dumpsys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> battery</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;powered: true&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> green</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span></code></pre></div><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><p>Inputs hold a value and export it as <code>$LABEL</code> (uppercased, snake-cased) on every run. Their <strong>On change</strong> setting is one of: <em>Refresh displays</em> that read the var, <em>Run a function</em> (the one derived from the label, fired on change — e.g. a toggle that broadcasts on flip), or <em>Do nothing</em>.</p><table tabindex="0"><thead><tr><th>Control</th><th>Value</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Text field</strong></td><td>string</td><td>Free text, e.g. a <code>$PACKAGE</code> name. Enable <strong>Multi-line</strong> for a resizable text area; newlines are preserved in the exported value.</td></tr><tr><td><strong>Slider</strong></td><td>number</td><td><code>min</code> / <code>max</code> / <code>step</code>; optional unit.</td></tr><tr><td><strong>Knob</strong></td><td>number</td><td>Same value model as the slider, rotary UI.</td></tr><tr><td><strong>Stepper</strong></td><td>number</td><td><code>−</code> / <code>+</code> by <code>step</code>, clamped to <code>min</code> / <code>max</code>.</td></tr><tr><td><strong>Toggle</strong></td><td><code>1</code> / <code>0</code></td><td>Test with <code>[ &quot;$VERBOSE&quot; = 1 ]</code>. Optional <strong>Values</strong> override the exported off / on pair (one per line).</td></tr><tr><td><strong>Select</strong></td><td>string</td><td>One of a fixed option list.</td></tr></tbody></table><p>Example — a <code>Package</code> text field ↦ <code>$PACKAGE</code>, and a <code>Brightness</code> slider (0–255) set to <em>Run a function</em> ↦ runs <code>set_brightness()</code> on every change.</p><h3 id="action-button" tabindex="-1">Action button <a class="header-anchor" href="#action-button" aria-label="Permalink to &quot;Action button&quot;">​</a></h3><p>Runs the function derived from its label (<code>Force stop</code> ↦ <code>force_stop</code>) once, exports all input values first, and sends stdout/stderr/exit to the console it&#39;s bound to. <strong>Variant</strong> styles it (Default / Subtle / Destructive); <strong>Confirm before running</strong> opens a Cancel / Run dialog first — use it for destructive actions.</p><h3 id="daemon" tabindex="-1">Daemon <a class="header-anchor" href="#daemon" aria-label="Permalink to &quot;Daemon&quot;">​</a></h3><p>Runs a function as a <strong>managed background process</strong>, for commands that keep running rather than finish — e.g. <code>watch() { logcat | grep &quot;$PACKAGE&quot;; }</code>. A daemon is declarative: it&#39;s a desired-state toggle, and the runtime starts or stops the process to match (akin to a service manager). The function derives from the label, exactly like an action button, and its output streams to the bound console.</p><ul><li><strong>Show controls</strong> (default off) — the whole control is a single clickable surface: a status LED (running / finished / error / stopped), the label, and a play/stop glyph. Clicking it starts or stops the daemon. With it off, the daemon runs headless and only its bound console shows anything — pair it with a console set to <em>Hide chrome</em> for a clean log pane.</li><li><strong>Auto-start</strong> (default on) — start the daemon when the dashboard loads. Always disarmed on import, so an imported panel never starts a process on its own; re-arm it from the builder.</li><li><strong>Restart</strong> (default <em>Never</em>) — what to do when the process exits, mirroring systemd&#39;s <code>Restart=</code>: <em>Never</em> leaves it in a terminal state; <em>On failure</em> relaunches after a non-zero exit; <em>On success</em> after a clean exit; <em>Always</em> after either. Restarts happen after a short delay so a fast-exiting command can&#39;t spin.</li></ul><p>When <strong>Restart</strong> is <em>Never</em> and the process exits on its own, the daemon enters a <strong>terminal</strong> state: a clean exit (0) shows <strong>finished</strong> (blue LED), a non-zero exit shows <strong>error</strong> (red LED). Click the control to run it again.</p><p>A daemon can <strong>clear its console</strong> by emitting a standard terminal clear — <code>clear</code>, <code>reset</code>, or <code>printf &#39;\\033[2J\\033[H&#39;</code>. This also lets a repainting command (a <code>top</code>-style refresh that clears and redraws) show only its latest frame instead of accumulating.</p><h3 id="displays" tabindex="-1">Displays <a class="header-anchor" href="#displays" aria-label="Permalink to &quot;Displays&quot;">​</a></h3><p>Displays run a <strong>bound function</strong> (on mount, on their poll interval, and optionally when an input they read changes) and render its output:</p><table tabindex="0"><thead><tr><th>Display</th><th>Renders the function&#39;s output as</th></tr></thead><tbody><tr><td><strong>Console</strong></td><td>The most recent run: the command, stdout, stderr, and exit code — or a live feed when a daemon targets it. Renders ANSI colours and emoji, and clears on a terminal clear sequence (<code>clear</code> / <code>\\033[2J</code>). Bound to &quot;last run&quot; rather than one function. <strong>Hide command line</strong> drops the leading <code>$ command</code> line; <strong>Hide chrome</strong> drops the whole header for an output-only pane; <strong>Auto-scroll</strong> pins it to the newest output.</td></tr><tr><td><strong>Readout</strong></td><td>The first number on the last non-empty line, plus a unit — e.g. <code>battery_temp</code> ↦ <code>31.2 °C</code>.</td></tr><tr><td><strong>Status pill</strong></td><td>The last line as text, coloured green / red by exit status.</td></tr><tr><td><strong>Gauge</strong></td><td>That number on a <code>min</code>/<code>max</code> arc (warns past ~85%).</td></tr><tr><td><strong>LED</strong></td><td>A colour from the output: the words <code>green</code> / <code>amber</code> / <code>red</code> / <code>blue</code> / <code>off</code>, else on (non-empty / non-zero) vs off. <code>charging</code> ↦ a green dot.</td></tr></tbody></table><p>Each bound display has <strong>Auto-poll</strong> (off by default; on ⇒ re-runs every N seconds) and <strong>Refresh on input change</strong> (re-run when an input its function reads changes).</p><h3 id="section" tabindex="-1">Section <a class="header-anchor" href="#section" aria-label="Permalink to &quot;Section&quot;">​</a></h3><p>A non-interactive heading (with optional description) that groups the controls below it. Display only — it doesn&#39;t scope the shell environment.</p><h2 id="the-builder" tabindex="-1">The builder <a class="header-anchor" href="#the-builder" aria-label="Permalink to &quot;The builder&quot;">​</a></h2><p>The tile&#39;s cog opens the builder: the shell script on the left (with a <strong>Run as root</strong> toggle and a live legend of the variables and functions in scope), the controls list and per-control settings on the right. Drag to reorder controls; the split between panes is draggable and the controls pane can collapse to give the editor the full width. Edits apply live as you make them — the script editor has line numbers and syntax highlighting. <strong>Clear</strong> resets the script and controls to the starting state.</p><p>If the script fails a syntax check on a real device, the tile shows a <strong>script error</strong> banner — click it to jump back into the builder — and the action buttons are disabled until it parses.</p><h2 id="sharing-a-panel" tabindex="-1">Sharing a panel <a class="header-anchor" href="#sharing-a-panel" aria-label="Permalink to &quot;Sharing a panel&quot;">​</a></h2><p>Scripting panels travel with the dashboard&#39;s <a href="./dashboard#sharing">import / export</a>. Because an imported panel runs shell commands on your device, the importer must acknowledge that explicitly, and auto-polling displays start <strong>paused</strong> after an import — nothing runs until you choose to enable it.</p><h2 id="trying-it-without-a-device" tabindex="-1">Trying it without a device <a class="header-anchor" href="#trying-it-without-a-device" aria-label="Permalink to &quot;Trying it without a device&quot;">​</a></h2><p>On the <a href="./simulator">simulated stream</a>, the widget evaluates a small subset of shell — <code>echo</code> / <code>printf</code> with <code>$VAR</code> substitution, including <code>echo -e</code> escapes for ANSI colours — so a demo panel produces real-looking output with no phone attached. Daemons loop their simulated output so you can watch a feed scroll without a device.</p>`,45))])}const b=n(h,[["render",c]]);export{y as __pageData,b as default};
